#!/bin/bash
# Task 159-w13-t2-ref -- meshsim sim/ WORKER13 (branch sim-w13 58aefa4; sim/ref, precompiled).
# sim/ref's TracerT2 on Quest 110u's runs: segment 10 of evm-zone-29 and cyclone-29, 64 windows, raw, C&C 1's CC_SEGMENT,
# in parallel, each checked against 110u's figures (sim/ref is v1.3 after a326fbd: WORKER28's idle-skip and the Tracer's
# statistics counters added; the images and tables are 110u's, byte for byte). Also lists the persistent data. Not timing.
# Expected ~25 min.
# From an embedded kit. Writes only results/159-w13-t2-ref/. Scratch in /tmp, removed first and at the end; inputs only read.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/159-w13-t2-ref; mkdir -p "$RES"
W=/tmp/w13-159-w13-t2-ref; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "3006d536333867f254c743571542dab36551d5a97cfd963c473f7b113e75f666" ] || { echo "kit sha256 mismatch (want 3006d536333867f254c743571542dab36551d5a97cfd963c473f7b113e75f666)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KR=$W/kit/run; KC=$W/kit/classes:$W/kit/gold; KT=$W/kit/tables/replayer; KS=$W/kit/sim
DATA=${T1_DATA:-$HOME/data}; [ -d "$DATA/w26-jumpmap" ] || DATA=$REPO/data
D9=$DATA/w9-deliveries; D26=$DATA/w26-jumpmap
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
# program : the delivery manifest's SHA-256 : WORKER26's manifest.sha256's SHA-256 (as 110u)
declare -A S9=([evm-zone-29]=7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f [cyclone-29]=f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982)
declare -A S26=([evm-zone-29]=57dc0ffe7574ab3e11f79f8414501bd1ceb2fd75faab0b03f3b4a6c2c61cad2d [cyclone-29]=ace78f61efbb9c0e418a0b1d7f54a79f6e299b7ff45ad7f09537b11961b95fba)
checkin() {
  local P=$1 A B
  A=$(sha256sum "$D9/$P.manifest.json" 2>/dev/null | cut -d' ' -f1); B=$(sha256sum "$D26/$P/manifest.sha256" 2>/dev/null | cut -d' ' -f1)
  [ "$A" = "${S9[$P]}" ] && [ "$(cat "$D9/$P.COMPLETE" 2>/dev/null)" = "$A" ] || { echo "$P: the delivery isn't complete or differs"; return 1; }
  [ "$B" = "${S26[$P]}" ] && [ "$(cat "$D26/$P.COMPLETE" 2>/dev/null)" = "$B" ] || { echo "$P: WORKER26's inputs aren't complete or differ"; return 1; }
  (cd "$D26/$P" && sha256sum -c --quiet manifest.sha256) || { echo "$P: WORKER26's files differ from their manifest"; return 1; }
  echo "$P: inputs checked (delivery $A, w26 $B)"
}
START=$(date +%s)
{
sec "machine (D21)"; . "$KS/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
cat "$W/kit/VERSION"; java -version 2>&1 | head -1; echo "persistent data: $DATA"
# t2-ref-body.sh (WORKER13): sim/ref's TracerT2 on 110u's two runs (segment 10 of evm-zone-29 and cyclone-29, 64 windows,
# raw, C&C 1's CC_SEGMENT), in parallel as 110u, against 110u's figures; and an inventory of the persistent data.
sec "the persistent data"
ls -la "$DATA"; du -sh "$DATA"/* 2>/dev/null; ls "$D9" | head -50; ls "$D26"
sec "inputs"
OKIN=1; for P in evm-zone-29 cyclone-29; do checkin $P || OKIN=0; done
[ $OKIN = 1 ] || { verdict inputs FAIL; }
if [ $OKIN = 1 ]; then
  sec "T2 on segment 10 of both workloads (sim/ref, idle-skip on: its default)"
  cd "$KR"
  J="java -Xmx${T1_HEAP:-5g} -Dreplay.tables=$KT -cp $KC TracerT2"
  PIDS=""
  for P in evm-zone-29 cyclone-29; do
    $J "$D9" $P --w26 "$D26/$P" --segments 10 --quiet --csv "$RES/$P-t.csv" > "$RES/$P-t.log" 2>&1 & PIDS="$PIDS $!:$P"
  done
  for X in $PIDS; do wait ${X%%:*}; echo "${X#*:}: exit $?"; cat "$RES/${X#*:}-t.log"; done
  # 110u: C&C 3 cycles, trace rows, drain, transfers, DMA packets, replay max, rows
  declare -A WANT=([evm-zone-29]="10,64,23693506,19531654,4129492,14162,1772179,234206,4194304" [cyclone-29]="10,64,28105942,23810180,4264156,15716,1974150,200588,4194304")
  for P in evm-zone-29 cyclone-29; do
    GOTL=$(tail -1 "$RES/$P-t.csv" 2>/dev/null | cut -d, -f1-9); OKL=$(tail -1 "$RES/$P-t.csv" 2>/dev/null | cut -d, -f11)
    echo "$P: got $GOTL ($OKL), 110u ${WANT[$P]}"
    [ "$GOTL" = "${WANT[$P]}" ] && [ "$OKL" = OK ] && verdict "$P-seg10-as-110u" PASS || verdict "$P-seg10-as-110u" FAIL
  done
fi
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
